/* ByteQuest profile: compact topic summary; scalable even with 100+ topics. */
.community-page::before{display:none!important}
.community-page .community-main{padding-top:18px!important}
.community-page #communityMessage[hidden]{display:none!important}
.community-page #profileAnalytics .topic-summary{
 display:block!important;
 margin:15px 0 24px!important;
 padding:22px 24px!important;
 border:1px solid var(--border);
 background:var(--surface)!important;
 border-radius:13px;
}
.community-page #profileAnalytics .topic-summary>div:first-child{
 display:flex;justify-content:space-between;align-items:baseline;
 gap:10px 24px;flex-wrap:wrap;
 margin-bottom:17px;
}
.community-page #profileAnalytics .topic-summary h2{
 margin:0!important;
 font:650 18px/1.35 var(--font-sans)!important;
 letter-spacing:-.025em;
}
.community-page #profileAnalytics .topic-summary>div:first-child p{
 margin:0!important;max-width:440px;
 font:400 11px/1.5 var(--font-sans)!important;
}
.community-page #profileAnalytics #topicBreakdown{
 max-width:none!important;
 width:100%;display:block;
}
.community-page #profileAnalytics .topic-coverage-stats{
 display:grid;grid-template-columns:repeat(3,minmax(0,1fr));
 gap:10px;
}
.community-page #profileAnalytics .topic-coverage-metric{
 min-width:0;
 background:var(--surface-2);
 border:1px solid var(--border);
 border-radius:9px;
 padding:13px 15px;
 display:flex;flex-direction:column;gap:6px;
}
.community-page #profileAnalytics .topic-coverage-metric strong{
 font:650 22px/1.2 var(--font-sans);
 color:var(--text);font-variant-numeric:tabular-nums;
 letter-spacing:-.035em;
}
.community-page #profileAnalytics .topic-coverage-metric small{
 font:450 12px var(--font-sans);color:var(--muted);
}
.community-page #profileAnalytics .topic-coverage-metric span{
 font:400 10px/1.4 var(--font-sans);color:var(--muted);
}
.community-page #profileAnalytics .topic-coverage-bottom{
 display:flex;align-items:center;justify-content:space-between;
 flex-wrap:wrap;gap:12px;
 margin-top:13px;
}
.community-page #profileAnalytics .topic-coverage-bottom p{
 margin:0!important;font:400 10px/1.5 var(--font-sans)!important;
 color:var(--muted)!important;
}
.community-page #profileAnalytics .topic-directory-toggle,
.community-page #profileAnalytics .topic-directory-pager button{
 border:1px solid var(--border);
 border-radius:7px;
 color:var(--text);
 background:var(--surface-2);
 padding:9px 12px;
 font:500 11px var(--font-sans);
 cursor:pointer;
}
.community-page #profileAnalytics .topic-directory-toggle:hover,
.community-page #profileAnalytics .topic-directory-pager button:hover:not(:disabled){
 border-color:var(--accent);color:var(--accent);
}
.community-page #profileAnalytics .topic-directory-toggle:focus-visible,
.community-page #profileAnalytics .topic-directory :is(input,select,button):focus-visible{
 outline:2px solid var(--accent);outline-offset:2px;
}
.community-page #profileAnalytics .topic-directory[hidden]{display:none!important}
.community-page #profileAnalytics .topic-directory{
 margin-top:19px;border-top:1px solid var(--border);padding-top:15px;
}
.community-page #profileAnalytics .topic-directory-filters{
 display:flex;align-items:center;gap:8px;
}
.community-page #profileAnalytics .topic-directory-filters :is(input,select){
 min-width:0;
 background:var(--surface-2);
 color:var(--text);
 border:1px solid var(--border);
 padding:10px 12px;
 border-radius:8px;
 font:400 11px var(--font-sans);
 min-height:38px;
}
.community-page #profileAnalytics .topic-directory-filters input{flex:1}
.community-page #profileAnalytics .topic-directory-filters select{flex:0 0 145px}
.community-page #profileAnalytics .topic-result-count{
 margin:11px 0 8px!important;font:450 10px var(--font-sans)!important;
 color:var(--muted)!important;
}
.community-page #profileAnalytics .topic-directory-row{
 display:grid;grid-template-columns:minmax(110px,1.2fr) minmax(90px,2fr) 65px 90px;
 align-items:center;gap:12px;
 min-height:42px;
 padding:8px 4px;
 border-bottom:1px solid var(--border);
 font:450 11px var(--font-sans);
}
.community-page #profileAnalytics .topic-directory-row:last-child{border-bottom:0}
.community-page #profileAnalytics .topic-directory-name{
 min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
 color:var(--text);font-weight:500;
}
.community-page #profileAnalytics .topic-directory-progress{
 display:block;height:6px;width:100%;background:var(--surface-2);
 border:1px solid var(--border);border-radius:5px;
 overflow:hidden;box-sizing:border-box;
}
.community-page #profileAnalytics .topic-directory-progress i{
 display:block;height:100%;
 background:var(--accent);border-radius:inherit;
}
.community-page #profileAnalytics .topic-directory-row strong{
 justify-self:end;color:var(--text);white-space:nowrap;
 font:600 11px var(--font-mono);
 font-variant-numeric:tabular-nums;
}
.community-page #profileAnalytics .topic-directory-gain{
 color:var(--muted);text-align:right;white-space:nowrap;font-size:9px;
}
.community-page #profileAnalytics .topic-directory-pager{
 display:flex;align-items:center;justify-content:flex-end;
 gap:10px;margin-top:13px;
}
.community-page #profileAnalytics .topic-directory-pager span{
 color:var(--muted);font:400 10px var(--font-mono);
}
.community-page #profileAnalytics .topic-directory-pager button:disabled{
 opacity:.4;cursor:default;
}
.community-page #profileAnalytics .topic-directory-empty,
.community-page #profileAnalytics .topic-unavailable{
 font:400 11px var(--font-sans)!important;color:var(--muted)!important;
 padding:11px 0;margin:0!important;
}
@media(max-width:650px){
 .community-page #profileAnalytics .topic-summary{padding:16px!important}
 .community-page #profileAnalytics .topic-coverage-stats{gap:6px}
 .community-page #profileAnalytics .topic-coverage-metric{
  padding:11px 9px;border-radius:7px;
 }
 .community-page #profileAnalytics .topic-coverage-metric strong{font-size:17px}
 .community-page #profileAnalytics .topic-coverage-metric span{font-size:9px}
 .community-page #profileAnalytics .topic-directory-filters{flex-wrap:wrap}
 .community-page #profileAnalytics .topic-directory-filters select{flex:1 1 130px}
 .community-page #profileAnalytics .topic-directory-row{
  grid-template-columns:minmax(0,1.15fr) minmax(60px,1fr) 53px;
  gap:8px;
 }
 .community-page #profileAnalytics .topic-directory-gain{display:none}
}

// Display-only topic navigation for arbitrarily large published catalogs.
// Counts are calculated upstream from distinct published problem IDs.
export function topicCoverageSummary(rows=[]){
 const topics=rows.length;
 const practiced=rows.filter(row=>row.solved>0).length;
 const completed=rows.filter(row=>row.total>0&&row.solved>=row.total).length;
 return {
  topics,practiced,completed,
  solved:rows.reduce((sum,row)=>sum+Math.min(Math.max(0,row.solved),row.total),0),
  total:rows.reduce((sum,row)=>sum+Math.max(0,row.total),0)
 };
}
export function topicExplorerPage(rows=[],{
 query='',status='all',page=0,pageSize=10
}={}){
 const search=String(query||'').trim().toLocaleLowerCase();
 const selected=['all','active','completed','unstarted'].includes(status)?status:'all';
 const matching=rows.filter(row=>{
  if(search&&!String(row.name||'').toLocaleLowerCase().includes(search))return false;
  if(selected==='active')return row.solved>0&&row.solved<row.total;
  if(selected==='completed')return row.total>0&&row.solved>=row.total;
  if(selected==='unstarted')return row.solved===0;
  return true;
 });
 const size=Math.min(20,Math.max(1,Number.isInteger(pageSize)?pageSize:10));
 const pages=Math.max(1,Math.ceil(matching.length/size));
 const current=Math.max(0,Math.min(pages-1,Math.floor(Number(page)||0)));
 return {items:matching.slice(current*size,(current+1)*size),
  count:matching.length,page:current,pages,pageSize:size};
}

const frame = (values, active, message, note = "", found = [], dim = []) => ({values,active,message,note,found,dim});
export function traceFor(p) {
  if(Array.isArray(p.frames)&&p.frames.length)return p.frames;
  if (p.id === "two-sum") return [
    frame([2,7,11,15],[], "We need two values that add up to 9. Start with an empty map.", "seen = {}"),
    frame([2,7,11,15],[0], "Visit 2. Its complement is 9 − 2 = 7. We have not seen 7 yet.", "need = 7 · not found"),
    frame([2,7,11,15],[0], "Remember the value 2 and its index. Check first, then insert.", "seen = {2 → 0}"),
    frame([2,7,11,15],[1], "Visit 7. Its complement is 9 − 7 = 2. Our map has it!", "need = 2 · found at index 0"),
    frame([2,7,11,15],[], "Return indices [0, 1]. The map avoids checking every possible pair.", "2 + 7 = 9", [0,1])
  ];
  if (p.id === "contains-duplicate") return [
    frame([1,2,3,1],[], "A set remembers which values have visited before.", "seen = {}"),
    frame([1,2,3,1],[0], "Add 1. This is its first visit.", "seen = {1}"),
    frame([1,2,3,1],[1], "Add 2. Still unique.", "seen = {1, 2}"),
    frame([1,2,3,1],[2], "Add 3. No duplicate yet.", "seen = {1, 2, 3}"),
    frame([1,2,3,1],[], "The next 1 is already in the set. Return true.", "1 is a repeated visitor",[0,3])
  ];
  if (p.id === "binary-search") return [
    frame([-1,0,3,5,9,12],[], "Search for 9. The whole array is our candidate interval.", "left = 0 · right = 5"),
    frame([-1,0,3,5,9,12],[2], "The midpoint is index 2, value 3. Since 3 < 9, discard this index and its left side.", "mid = 2 · move left to 3"),
    frame([-1,0,3,5,9,12],[4], "The new midpoint is index 4. The value is 9.", "left = 3 · right = 5 · mid = 4",[],[0,1,2]),
    frame([-1,0,3,5,9,12],[], "Found it! Return 4. Every unsuccessful comparison halves the interval.", "answer = 4",[4],[0,1,2])
  ];
  if (p.id === "lower-bound") return [
    frame([1,3,3,5],[], "Find the first value at least 3. Use [left, right) with right = 4.", "left = 0 · right = 4"),
    frame([1,3,3,5],[2], "Value 3 qualifies, but there may be an earlier one. Keep mid as a candidate.", "mid = 2 → right = 2"),
    frame([1,3,3,5],[1], "Value 3 qualifies again. Move right to 1.", "mid = 1 → right = 1",[],[2,3]),
    frame([1,3,3,5],[0], "Value 1 is too small. Everything through index 0 can be discarded.", "mid = 0 → left = 1",[],[2,3]),
    frame([1,3,3,5],[], "left equals right. Index 1 is the first qualifying position.", "answer = 1",[1],[0,2,3])
  ];
  if (p.id === "sorted-squares") return [
    frame([-4,-1,0,3,10],[0,4], "Compare absolute values at both ends. The larger square goes at the back.", "output = [_, _, _, _, _]"),
    frame([-4,-1,0,3,10],[0,4], "|10| beats |−4|. Place 100 at the end and move right inward.", "output = [_, _, _, _, 100]"),
    frame([-4,-1,0,3,10],[0,3], "|−4| beats |3|. Place 16 next and move left inward.", "output = [_, _, _, 16, 100]"),
    frame([-4,-1,0,3,10],[1,3], "|3| beats |−1|. Place 9.", "output = [_, _, 9, 16, 100]"),
    frame([-4,-1,0,3,10],[1,2], "Place 1, then 0. Filling from the back keeps the result sorted.", "output = [0, 1, 9, 16, 100]",[0,1,2,3,4])
  ];
  if (p.id === "valid-palindrome") return [
    frame(["a","b","b","a"],[0,3], "Compare the outer characters of abba.", "left = 0 · right = 3"),
    frame(["a","b","b","a"],[0,3], "a equals a. Move both pointers inward.", "outer pair matches",[0,3]),
    frame(["a","b","b","a"],[1,2], "b equals b. This pair matches too.", "inner pair matches",[0,3]),
    frame(["a","b","b","a"],[], "The pointers crossed. Every pair matched: return true.", "When reading real input, skip punctuation first.",[0,1,2,3])
  ];
  if (p.id === "move-zeroes") return [
    frame([0,1,0,3,12],[0], "Read each value. write marks the next slot for a nonzero value.", "write = 0"),
    frame([1,1,0,3,12],[1], "Read 1 and copy it to index 0. Advance write.", "write = 1 · built prefix = [1]",[0]),
    frame([1,1,0,3,12],[2], "Read 0. Skip it; leave write where it is.", "write = 1",[0]),
    frame([1,3,0,3,12],[3], "Read 3 and copy it to index 1.", "write = 2 · built prefix = [1, 3]",[0,1]),
    frame([1,3,12,3,12],[4], "Read 12 and copy it to index 2. The useful prefix is complete.", "write = 3",[0,1,2]),
    frame([1,3,12,0,0],[], "Fill the remaining positions with zeroes. The nonzero order is unchanged.", "return nums",[0,1,2,3,4])
  ];
  if (p.id === "window-sum") return [
    frame([1,12,-5,-6,50,3],[0,1,2,3], "The first width-4 window sums to 2.", "sum = 2 · best = 2"),
    frame([1,12,-5,-6,50,3],[1,2,3,4], "Slide once: subtract 1 and add 50. No need to rescan the middle.", "sum = 2 − 1 + 50 = 51 · best = 51",[],[0]),
    frame([1,12,-5,-6,50,3],[2,3,4,5], "Slide again: subtract 12 and add 3. The new sum is 42.", "sum = 51 − 12 + 3 = 42 · best = 51",[],[0,1]),
    frame([1,12,-5,-6,50,3],[], "Return the largest sum seen: 51.", "The best window is [12, −5, −6, 50].",[1,2,3,4])
  ];
  if (p.id === "valid-parentheses") return [
    frame(["{","[","]","}"],[], "A stack remembers the closing brackets we expect.", "stack = []"),
    frame(["{","[","]","}"],[0], "Read {. Push its partner }.", "stack = [}] · top on the right"),
    frame(["{","[","]","}"],[1], "Read [. Its partner ] must close before }.", "stack = [}, ]]"),
    frame(["{","[","]","}"],[2], "Read ]. It matches the stack top, so pop it.", "stack = [}]"),
    frame(["{","[","]","}"],[3], "Read }. It matches and empties the stack. Return true.", "stack = []",[0,1,2,3])
  ];
  if (p.id === "valid-anagram") return [
    frame(["l","i","s","t","e","n"],[], "listen and silent have the same length. Compare letter counts.", "Count up for s. Count down for t."),
    frame(["l","i","s","t","e","n"],[0,1,2,3,4,5], "First count the letters in listen.", "e:1  i:1  l:1  n:1  s:1  t:1"),
    frame(["s","i","l","e","n","t"],[0,1,2,3,4,5], "Subtract the letters in silent. Each increment is balanced.", "e:0  i:0  l:0  n:0  s:0  t:0"),
    frame(["s","i","l","e","n","t"],[], "Every counter is zero, so return true. Equal lengths alone would not be enough.", "An anagram preserves all frequencies.",[0,1,2,3,4,5])
  ];
  if (p.id === "gcd") return [
    frame([48,18],[0,1], "Euclid's algorithm keeps the GCD unchanged while shrinking the problem.", "a = 48 · b = 18"),
    frame([18,12],[0,1], "48 % 18 = 12. Replace the pair with (18, 12).", "gcd(48, 18) = gcd(18, 12)"),
    frame([12,6],[0,1], "18 % 12 = 6. Replace the pair with (12, 6).", "gcd(18, 12) = gcd(12, 6)"),
    frame([6,0],[], "12 % 6 = 0. Stop: the answer is 6.", "return a = 6",[0])
  ];
  if (p.id === "count-primes") return [
    frame([2,3,4,5,6,7,8,9],[], "Count primes strictly below 10. Start with candidates from 2 onward.", "0 and 1 are never prime."),
    frame([2,3,4,5,6,7,8,9],[0], "2 is prime. Mark its multiples starting at 2² = 4.", "Mark 4, 6, 8.",[0],[2,4,6]),
    frame([2,3,4,5,6,7,8,9],[1], "3 is prime. Mark its multiples starting at 3² = 9.", "Mark 9.",[0,1],[2,4,6,7]),
    frame([2,3,4,5,6,7,8,9],[], "The unmarked numbers are 2, 3, 5 and 7. Return 4.", "count = 4",[0,1,3,5],[2,4,6,7])
  ];
  if (p.trace === "dp") {
    const isStairs = p.id === "climb-stairs";
    const values = isStairs ? [1,1,2,3,5,8] : [0,1,1,2,3,5,8];
    return values.map((v,i) => frame(values,[i],i < 2 ? "Start with the base cases. These anchor every later result." : "Add the previous two states: " + values[i-2] + " + " + values[i-1] + " = " + v + ". Keep only those two numbers for the next step.", (isStairs ? "ways(" : "F(") + i + ") = " + v, Array.from({length:i},(_,j)=>j), Array.from({length:values.length-i-1},(_,j)=>j+i+1)));
  }
  if (p.id === "max-profit") return [
    frame([7,1,5,3,6,4],[0], "Start with the first price. You cannot make a profit yet.", "lowest = 7 · best = 0"),
    frame([7,1,5,3,6,4],[1], "1 is a new lower purchase price. Remember it.", "lowest = 1 · best = 0"),
    frame([7,1,5,3,6,4],[2], "Selling at 5 after buying at 1 earns 4.", "lowest = 1 · best = 4",[1,2]),
    frame([7,1,5,3,6,4],[3], "Selling at 3 would earn 2. Keep the better profit.", "lowest = 1 · best = 4",[1,2]),
    frame([7,1,5,3,6,4],[4], "Selling at 6 improves the profit to 5.", "lowest = 1 · best = 5",[1,4]),
    frame([7,1,5,3,6,4],[5], "4 gives a smaller profit. Return the best seen, 5.", "answer = 5",[1,4])
  ];
  if(p.id === "max-subarray") return [
    frame([-2,1,-3,4,-1,2,1,-5,4],[0], "Initialize from the first value. A nonempty answer may be negative.", "endingHere = −2 · best = −2"),
    frame([-2,1,-3,4,-1,2,1,-5,4],[1], "Start fresh at 1: it is better than extending the sum −2.", "endingHere = 1 · best = 1"),
    frame([-2,1,-3,4,-1,2,1,-5,4],[2], "Extend to −2. The overall best stays 1.", "endingHere = −2 · best = 1"),
    frame([-2,1,-3,4,-1,2,1,-5,4],[3], "Start fresh at 4. A negative prefix would reduce the sum.", "endingHere = 4 · best = 4",[3]),
    frame([-2,1,-3,4,-1,2,1,-5,4],[4,5,6], "Extend through −1, 2 and 1. The running sum reaches 6.", "endingHere = 6 · best = 6",[3,4,5,6]),
    frame([-2,1,-3,4,-1,2,1,-5,4],[], "The remaining values never improve on 6. Return 6.", "best subarray = [4, −1, 2, 1]",[3,4,5,6])
  ];
  return [frame(["?"],[],"An animation has not been added for this problem yet. Use the pattern guide and sketch the state changes as you practise.","Your Java still runs normally in the editor.")];
}

/* Server acceptance and browser practice must never look equivalent. */
.submission-verification-unavailable{
  padding:16px 18px;margin:14px 0;border:1px solid var(--border,#34383a);
  border-radius:12px;background:var(--surface,#111416);color:var(--text,#f1f4f2);
  font:13px/1.55 Inter,system-ui,sans-serif;
}
.submission-verification-unavailable strong{font-size:14px;font-weight:600;display:block;margin:0 0 6px}
.submission-verification-unavailable p{margin:7px 0;color:var(--muted,#abb3af);line-height:1.6}
.submission-verification-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:15px}
.submission-locked [data-verify-submit]{margin-top:12px}
@media(max-width:600px){
  .submission-verification-unavailable{padding:13px 14px}
  .submission-verification-actions .button{max-width:100%;white-space:normal}
}

// Browser practice and server verification are separate kinds of evidence.
// The browser cannot execute a private suite, and a counted personal practice
// solve is never proof that the hidden cases passed.
export function practiceVerificationSummary(problem,attempt){
  const publicTotal=Number.isSafeInteger(attempt?.total)&&attempt.total>0?attempt.total:0;
  const publicPassed=Number.isSafeInteger(attempt?.passed)&&attempt.passed>=0?Math.min(attempt.passed,publicTotal):0;
  const hiddenTotal=Number.isSafeInteger(problem?.hiddenCount)&&problem.hiddenCount>=0?problem.hiddenCount:0;
  return {
    title:'Practice accepted · server verification pending',
    tests:publicPassed+'/'+publicTotal+' browser practice cases passed',
    hidden:hiddenTotal>0?'0/'+hiddenTotal+' private hidden cases verified':'No private hidden cases advertised',
    explanation:'This solve is recorded toward personal progress, but no server-verified acceptance has been recorded for it. Community rankings and protected reference solutions require successful server verification.'
  };
}
export function privateJudgeUnavailableSummary(problem){
  const hiddenTotal=Number.isSafeInteger(problem?.hiddenCount)&&problem.hiddenCount>0?problem.hiddenCount:0;
  return {
    title:'Private Java verification unavailable',
    hidden:hiddenTotal?'0/'+hiddenTotal+' hidden cases confirmed by the server':'No server acceptance recorded',
    explanation:'Your source has not been marked server-accepted. The private judge must be configured and available for this problem. You can explicitly run browser practice, but passing it does not establish hidden-case acceptance.'
  };
}

import {avatarKeyFromSignedUrl,warmAvatarImages,clearAvatarImages} from "./avatar-cache.js?v=avatar-1";
// Account-scoped, short-lived page view cache. Chat, notifications, online
// presence, Firebase identity, and private progress never pass through this module.
export const LEADERBOARD_TTL_MS=5*60*1000;
export const PROFILE_TTL_MS=2*60*1000;
export const ACCOUNT_TTL_MS=2*60*1000;
export const STALE_VIEW_MAX_MS=24*60*60*1000;
const PREFIX="bytequest.views.v1:";
const MAX_ENTRY_BYTES=750000;
// Private avatar links are signed by the server for 600 seconds; old cache
// snapshots must fall back to initials rather than display expired image URLs.
const SIGNED_AVATAR_SAFE_AGE_MS=8*60*1000;
function avatarStillValid(row,age){
  if(!row||age<SIGNED_AVATAR_SAFE_AGE_MS||typeof row.avatar_url!=="string"
    ||!row.avatar_url.includes("/storage/v1/object/sign/bytequest-avatars/"))return row;
  return {...row,avatar_url:"",avatar_cache_key:avatarKeyFromSignedUrl(row.avatar_url)};
}
function safeCachedImages(kind,value,age){
  if(age<SIGNED_AVATAR_SAFE_AGE_MS)return value;
  if(kind==="board")return {
    ...value,
    users:value.users.map(row=>avatarStillValid(row,age)),
    me:avatarStillValid(value.me,age)
  };
  if(kind==="profile")return {...value,profile:avatarStillValid(value.profile,age)};
  return value;
}
function browserSession(){
  try{return globalThis.sessionStorage||null;}catch{return null;}
}
function validBoard(value){
  return !!value&&typeof value==="object"&&Array.isArray(value.users)
    &&Number.isFinite(value.total)&&value.total>=0;
}
function validProfile(value){
  return !!value&&typeof value==="object"&&!!value.profile
    &&typeof value.profile.public_id==="string"
    &&typeof value.profile.username==="string"
    &&value.stats&&typeof value.stats==="object";
}
function validAccount(value){
  return !!value&&typeof value==="object"&&typeof value.admin==="boolean"
    &&(value.profile===null||
      !!value.profile&&typeof value.profile==="object"
      &&typeof value.profile.public_id==="string"
      &&typeof value.profile.username==="string");
}
export function createViewCache({storage=browserSession(),now=()=>Date.now()}={}){
  const key=(owner,kind,identity)=>owner&&typeof identity==="string"
    ?PREFIX+encodeURIComponent(owner)+":"+kind+":"+encodeURIComponent(identity):null;
  function read(owner,kind,identity,ttl,validate,allowStale=false){
    const id=key(owner,kind,identity);
    if(!id||!storage)return null;
    try{
      const raw=storage.getItem(id);
      if(!raw||raw.length>MAX_ENTRY_BYTES)return null;
      const entry=JSON.parse(raw),age=now()-entry.at;
      if(entry.version!==1||!Number.isFinite(age)||age<0||age>=(allowStale?STALE_VIEW_MAX_MS:ttl)||!validate(entry.value))return null;
      return safeCachedImages(kind,entry.value,age);
    }catch{return null;}
  }
  function write(owner,kind,identity,value,validate){
    const id=key(owner,kind,identity);
    if(!id||!storage||!validate(value))return;
    try{
      const raw=JSON.stringify({version:1,at:now(),value});
      if(raw.length<=MAX_ENTRY_BYTES)storage.setItem(id,raw);
    }catch{} // Storage restrictions and quota limits must never interrupt navigation.
  }
  function remove(owner,kind,identity){
    try{const id=key(owner,kind,identity);if(id)storage?.removeItem(id);}catch{}
  }
  function clearOwner(owner){
    if(!owner)return;
    void clearAvatarImages(owner);
    if(!storage)return;
    try{
      const prefix=PREFIX+encodeURIComponent(owner)+":",items=[];
      for(let i=0;i<storage.length;i++){
        const item=storage.key(i);
        if(typeof item==="string"&&item.startsWith(prefix))items.push(item);
      }
      for(const item of items)storage.removeItem(item);
    }catch{}
  }
  const boardId=({scope="global",period="all",page=0}={})=>scope+":"+period+":"+page;
  return {
    board(owner,query,{allowStale=false}={}){return read(owner,"board",boardId(query),LEADERBOARD_TTL_MS,validBoard,allowStale);},
    self(owner){return read(owner,"self","current",ACCOUNT_TTL_MS,validAccount);},
    saveSelf(owner,response){
      if(!response||typeof response!=="object")return;
      // Only the fields required for immediate profile navigation, never tokens,
      // progress, notifications, messages, or live presence.
      write(owner,"self","current",{admin:response.admin===true,profile:response.profile??null},validAccount);
    },
    saveBoard(owner,query,value){
      write(owner,"board",boardId(query),value,validBoard);
      if(validBoard(value))void warmAvatarImages(owner,[...value.users,value.me]);
    },
    invalidateBoard(owner,query){remove(owner,"board",boardId(query));},
    profile(owner,target,{allowStale=false}={}){return read(owner,"profile",String(target||"").toLowerCase(),PROFILE_TTL_MS,validProfile,allowStale);},
    saveProfile(owner,target,value){
      if(!validProfile(value))return;
      // Do not persist presence: live online and last-seen are fetched independently.
      const {presence,...stable}=value;
      write(owner,"profile",String(target||"").toLowerCase(),stable,validProfile);
      void warmAvatarImages(owner,[value.profile]);
    },
    invalidateProfile(owner,target){remove(owner,"profile",String(target||"").toLowerCase());},
    clearOwner
  };
}

/** Warm only the initial public-facing ranking and the user's own profile.
 * This is optional: any network failure leaves normal on-demand fetch intact.
 * Never prefetch chat, notifications, presence, tokens, or private progress.
 */
export async function prefetchCommunityViews(cloud,{owner,profile,cache=createViewCache()}={}){
  if(!owner||cloud?.user?.id!==owner)return [];
  const jobs=[];
  const defaultBoard={scope:"global",period:"all",page:0};
  if(!cache.board(owner,defaultBoard,{allowStale:true})){
    jobs.push(cloud.request("leaderboard",defaultBoard,owner).then(result=>{
      if(cloud.user?.id===owner)cache.saveBoard(owner,defaultBoard,result);
    }));
  }
  const username=profile?.username;
  if(typeof username==="string"&&username&&!cache.profile(owner,username,{allowStale:true})){
    jobs.push(cloud.request("profile",{target:username},owner).then(result=>{
      if(cloud.user?.id===owner)cache.saveProfile(owner,username,result);
    }));
  }
  return Promise.allSettled(jobs);
}

